from __future__ import annotations

from dataclasses import dataclass, field
from collections.abc import Mapping
from pathlib import Path
import re
from typing import Any

from .models import PlanStep, ToolName


@dataclass(frozen=True)
class OperationSpec:
    name: str
    tool: ToolName
    description: str
    version: str = "1.0"
    compatible_versions: tuple[str, ...] = ()
    required_parameters: tuple[str, ...] = ()
    output_kinds: tuple[str, ...] = ()
    parameters_schema: dict[str, Any] = field(default_factory=dict)
    output_schema: dict[str, Any] = field(default_factory=dict)
    side_effects: tuple[str, ...] = ()
    safety: str = "safe"
    parameter_alternatives: tuple[tuple[str, ...], ...] = ()

    def schema(self) -> dict[str, Any]:
        parameters = dict(self.parameters_schema)
        outputs = self.output_schema
        if self.name.startswith(("catia.", "ansys.", "adams.", "vi-grade.")):
            parameters.update({
                "project_dir": {"type": "string", "description": "Project containing the configured action script and input files"},
                "dry_run": {"type": "boolean", "default": True},
                "inputs": {"type": "array", "items": {"type": "string"}, "description": "Project-relative files transferred to the software worker"},
                "outputs": {"type": "array", "items": {"type": "string"}, "description": "Required result files; defaults to configured action outputs"},
                "validation": {"type": "object", "description": "Custom report contract or built-in evidence kind; configured binding takes precedence", "properties": {"kind": {"type": "string", "enum": ["catia_parameters", "mechanical_solve", "adams_export", "vi_grade_export"]}, "report": {"type": "string"}, "required_checks": {"type": "array", "items": {"type": "string"}}}},
            })
            outputs = {"step_id": {"type": "string"}, "tool": {"type": "string"},
                       "status": {"type": "string", "enum": ["planned", "completed", "failed", "unavailable"]},
                       "message": {"type": "string"}, "outputs": {"type": "array", "items": {"type": "string"}},
                       "details": {"type": "object", "description": "File receipts, execution logs and transaction status; not proof of engineering validity"}}
        return {
            "name": self.name,
            "tool": self.tool.value,
            "description": self.description,
            "version": self.version,
            "compatible_versions": list(self.compatible_versions),
            "required_parameters": list(self.required_parameters),
            "output_kinds": list(self.output_kinds),
            "parameters_schema": parameters,
            "output_schema": outputs,
            "side_effects": list(self.side_effects),
            "safety": self.safety,
            "parameter_alternatives": [list(group) for group in self.parameter_alternatives],
        }


METRIC_PARAMETERS = {
    "required_metrics": {"type": "array", "items": {"type": "string"}, "minItems": 1, "uniqueItems": True},
    "metric_units": {"type": "object", "additionalProperties": {"type": "string"}, "description": "Expected unit for every required metric; unsupported or incompatible units are rejected"},
    "metric_rules": {"type": "array", "items": {"type": "object", "required": ["name", "operator", "target", "unit"], "properties": {
        "name": {"type": "string"}, "operator": {"type": "string", "enum": ["<", "<=", "=", "==", ">", ">="]},
        "target": {"type": "number"}, "unit": {"type": "string"}}}},
    "metric_columns": {"type": "object", "description": "Required for CSV exports: map metric names to explicit column, unit and reducer", "additionalProperties": {
        "type": "object", "required": ["column", "unit", "reducer"], "properties": {"column": {"type": "string"},
        "unit": {"type": "string"}, "reducer": {"type": "string", "enum": ["min", "max", "abs_max", "last"]}}}},
}


