class OperationRegistry:
    def __init__(self, specs: tuple[OperationSpec, ...] = OPERATION_SPECS):
        self.specs = {spec.name: spec for spec in specs}

    def list(self) -> list[dict[str, Any]]:
        return [self.specs[name].schema() for name in sorted(self.specs)]

    def get(self, name: str) -> OperationSpec:
        try:
            return self.specs[name]
        except KeyError as exc:
            raise ValueError(f"UNKNOWN_OPERATION:{name}") from exc

    def validate(self, name: str, parameters: dict[str, Any] | None = None) -> list[str]:
        spec = self.get(name)
        parameters = parameters or {}
        missing = [key for key in spec.required_parameters
                   if key not in parameters or parameters[key] is None or parameters[key] == ""]
        missing.extend("|".join(group) for group in spec.parameter_alternatives
                       if not any(key in parameters and parameters[key] is not None and parameters[key] != "" for key in group))
        return missing

    @staticmethod
    def _type_matches(expected: str, value: Any) -> bool:
        if expected == "string":
            # File arguments commonly arrive as pathlib.Path through the
            # Python API while MCP/HTTP clients use JSON strings.
            return isinstance(value, (str, Path))
        if expected == "number":
            return isinstance(value, (int, float)) and not isinstance(value, bool)
        if expected == "integer":
            return isinstance(value, int) and not isinstance(value, bool)
        if expected == "boolean":
            return isinstance(value, bool)
        if expected == "array":
            return isinstance(value, (list, tuple))
        if expected == "object":
            return isinstance(value, Mapping)
        if expected == "null":
            return value is None
        return True

    def _validate_schema_value(self, value: Any, schema: dict[str, Any], path: str) -> list[str]:
        if not isinstance(schema, dict):
            return []
        errors: list[str] = []
        expected = schema.get("type")
        if expected and not self._type_matches(str(expected), value):
            return [f"{path}:TYPE_{str(expected).upper()}"]
        if "enum" in schema and value not in schema["enum"]:
            errors.append(f"{path}:ENUM")
        if isinstance(value, (str, Path)) and schema.get("pattern"):
            if re.fullmatch(str(schema["pattern"]), str(value)) is None:
                errors.append(f"{path}:PATTERN")
        if isinstance(value, (int, float)) and not isinstance(value, bool):
            try:
                numeric = float(value)
                if "minimum" in schema and numeric < float(schema["minimum"]): errors.append(f"{path}:MINIMUM")
                if "exclusiveMinimum" in schema and numeric <= float(schema["exclusiveMinimum"]): errors.append(f"{path}:EXCLUSIVE_MINIMUM")
                if "maximum" in schema and numeric > float(schema["maximum"]): errors.append(f"{path}:MAXIMUM")
                if "exclusiveMaximum" in schema and numeric >= float(schema["exclusiveMaximum"]): errors.append(f"{path}:EXCLUSIVE_MAXIMUM")
            except (TypeError, ValueError):
                errors.append(f"{path}:NUMBER")
        if isinstance(value, (str, list, tuple, Mapping)):
            size = len(value)
            if "minItems" in schema and isinstance(value, (list, tuple)) and size < int(schema["minItems"]): errors.append(f"{path}:MIN_ITEMS")
            if "maxItems" in schema and isinstance(value, (list, tuple)) and size > int(schema["maxItems"]): errors.append(f"{path}:MAX_ITEMS")
            if "minProperties" in schema and isinstance(value, Mapping) and size < int(schema["minProperties"]): errors.append(f"{path}:MIN_PROPERTIES")
            if "maxProperties" in schema and isinstance(value, Mapping) and size > int(schema["maxProperties"]): errors.append(f"{path}:MAX_PROPERTIES")
            if "minLength" in schema and isinstance(value, str) and size < int(schema["minLength"]): errors.append(f"{path}:MIN_LENGTH")
            if "maxLength" in schema and isinstance(value, str) and size > int(schema["maxLength"]): errors.append(f"{path}:MAX_LENGTH")
        if isinstance(value, (list, tuple)) and isinstance(schema.get("items"), dict):
            for index, item in enumerate(value):
                errors.extend(self._validate_schema_value(item, schema["items"], f"{path}[{index}]"))
            if schema.get("uniqueItems"):
                try:
                    if len({repr(item) for item in value}) != len(value): errors.append(f"{path}:UNIQUE_ITEMS")
                except TypeError:
                    pass
        if isinstance(value, Mapping):
            for required in schema.get("required", []):
                if required not in value or value[required] is None:
                    errors.append(f"{path}.{required}:REQUIRED")
            for key, child in schema.get("properties", {}).items():
                if key in value and value[key] is not None:
                    errors.extend(self._validate_schema_value(value[key], child, f"{path}.{key}"))
            additional = schema.get("additionalProperties")
            if isinstance(additional, dict):
                declared = set(schema.get("properties", {}))
                for key, item in value.items():
                    if key not in declared:
                        errors.extend(self._validate_schema_value(item, additional, f"{path}.{key}"))
        return errors

    def validate_arguments(self, name: str, parameters: dict[str, Any] | None = None) -> list[str]:
        """Validate required fields and the published parameter schema.

        This is deliberately a small dependency-free JSON-schema subset.  It
        keeps Python, HTTP and MCP calls on the same contract while allowing
        path-like values from the native Python API.
        """
        spec = self.get(name)
        parameters = parameters or {}
        errors = [f"MISSING_PARAMETER:{key}" for key in self.validate(name, parameters)]
        for key, schema in spec.parameters_schema.items():
            if key in parameters and parameters[key] is not None:
                errors.extend(self._validate_schema_value(parameters[key], schema, key))
        return errors

    def validate_step(self, step: PlanStep) -> list[str]:
        operation = f"{step.tool.value}.{step.action}"
        if operation not in self.specs:
            # Existing planners use friendly actions; map them to typed names.
            aliases = {
                "catia.create_or_update_model": "catia.create_model",
                "ansys.mesh_and_solve": "ansys.mesh_and_solve",
                "adams.build_and_run_multibody": "adams.build_and_run_multibody",
                "vi-grade.run_vehicle_dynamics": "vi-grade.run_scenario",
            }
            operation = aliases.get(operation, operation)
        try:
            missing = self.validate(operation, step.parameters)
        except ValueError as exc:
            return [str(exc)]
        return [f"MISSING_PARAMETER:{key}" for key in missing]
